#include <iostream>
#include <string>

int main() {
    std::string x;
    std::getline(std::cin, x);
    for (size_t i = 1; i + 1 < x.length(); ++i) {
        if (x.substr(i, 2) == "at") {
            x = x.substr(0, i) + "@" + x.substr(i + 2);
            break;
        }
    }
    size_t pos = 0;
    while ((pos = x.find("dot")) != std::string::npos) {
        x.replace(pos, 3, ".");
    }
    if (!x.empty() && x[0] == '.') {
        x = "dot" + x.substr(1);
    }
    if (!x.empty() && x.back() == '.') {
        x = x.substr(0, x.size() - 1) + "dot";
    }
    std::cout << x << std::endl;
    return 0;
}
